/* Token primitives, pushed as a code asset by push-site.mjs.
   These CANNOT live in the style registry: happy-dom drops --custom-property
   declarations during conversion, silently. Edit site-src/css/ and re-push. */

/* ===== @font-face, rewritten to the uploaded variable woff2 ===== */
@font-face{font-family:'Bodoni Moda';font-style:normal;font-weight:400 900;font-display:swap;
  src:url("/uploads/z8dqn_QR6sN7LsL252Q0h-bodoni-moda-var.woff2") format('woff2')}
@font-face{font-family:'Bodoni Moda';font-style:italic;font-weight:400 900;font-display:swap;
  src:url("/uploads/Jju4VlXaQSuLzXAaIDiMl-bodoni-moda-italic-var.woff2") format('woff2')}
@font-face{font-family:'Manrope';font-style:normal;font-weight:200 800;font-display:swap;
  src:url("/uploads/i342JgceepizMxsObsCtL-manrope-var.woff2") format('woff2')}

/* ===== 00-fluid-root.css ===== */
:root { --font-from: 18; --font-to: 20; --vw-from: calc(1920 / 100); --vw-to: calc(2400 / 100); --coefficient: calc((var(--font-to) - var(--font-from)) / (var(--vw-to) - var(--vw-from))); --base: calc((var(--font-from) - var(--vw-from) * var(--coefficient)) / 16); }
@media screen and (max-width: 1920px) {:root { --font-from: 16; --font-to: 18; --vw-from: calc(1440 / 100); --vw-to: calc(1920 / 100); }}
@media screen and (max-width: 1440px) {:root { --font-from: 16; --font-to: 16; --vw-from: calc(479 / 100); --vw-to: calc(1440 / 100); }}
@media screen and (max-width: 479px) {:root { --font-from: 12; --font-to: 16; --vw-from: calc(320 / 100); --vw-to: calc(479 / 100); }}

/* ===== 01-tokens.css ===== */
:root { --ground:#11110F; --ground-2:#191815; --ground-3:#1F1D19; --ground-deep:#090909; --ground-ink:#080808; --ink:#F4EFE5; --ink-muted:#B5AFA4; --ink-dim:rgba(244,239,229,.55); --gold:#C4A36A; --gold-deep:#8F7442; --gold-soft:rgba(196,163,106,.18); --line:rgba(244,239,229,.14); --line-soft:rgba(244,239,229,.08); --paper:#F4EFE5; --paper-2:#EAE3D6; --paper-ink:#11110F; --paper-muted:#5E574C; --serif:'Bodoni Moda',Georgia,'Times New Roman',serif; --sans:'Manrope',system-ui,-apple-system,'Segoe UI',Arial,sans-serif; --t-display:6.4rem; --t-h2:4.4rem; --t-h3:2.1rem; --t-quote:2.4rem; --t-lead:1.2rem; --t-body:1.06rem; --t-small:.82rem; --t-micro:.66rem; --wrap:82rem; --gutter:clamp(1.25rem,4vw,4rem); --nav-h:5.25rem; --ease-out:cubic-bezier(.16,1,.3,1); --ease-in-out:cubic-bezier(.65,0,.35,1); }
@media (max-width:1023px) {:root { --t-display:4.6rem; --t-h2:3.3rem; --t-h3:1.8rem; --t-quote:1.9rem; --nav-h:4.5rem; }}
@media (max-width:767px) {:root { --t-display:3.6rem; --t-h2:2.7rem; --t-h3:1.6rem; --t-quote:1.65rem; --t-lead:1.16rem; --t-body:1.16rem; --t-small:.9rem; --t-micro:.72rem; }}

/* ===== the cascade of every pair the conversion is lossy on — a clamp()/min()/max()
        value, or a multi-layer background — from 02-base.css. See push-site.mjs ===== */
html { -webkit-text-size-adjust: 100%; }
html { scroll-behavior: auto; }
.serif { font-variation-settings: 'opsz' 36; }
.display { font-variation-settings: 'opsz' 48; }
.h2 { font-variation-settings: 'opsz' 42; }
.h3 { font-variation-settings: 'opsz' 36; }
@media (prefers-reduced-motion:reduce) { * { animation-duration: .001ms!important; } }
@media (prefers-reduced-motion:reduce) { *::before { animation-duration: .001ms!important; } }
@media (prefers-reduced-motion:reduce) { *::after { animation-duration: .001ms!important; } }
@media (prefers-reduced-motion:reduce) { * { animation-iteration-count: 1!important; } }
@media (prefers-reduced-motion:reduce) { *::before { animation-iteration-count: 1!important; } }
@media (prefers-reduced-motion:reduce) { *::after { animation-iteration-count: 1!important; } }
@media (prefers-reduced-motion:reduce) { * { transition-duration: .001ms!important; } }
@media (prefers-reduced-motion:reduce) { *::before { transition-duration: .001ms!important; } }
@media (prefers-reduced-motion:reduce) { *::after { transition-duration: .001ms!important; } }
@media (prefers-reduced-motion:reduce) { * { scroll-behavior: auto!important; } }
@media (prefers-reduced-motion:reduce) { *::before { scroll-behavior: auto!important; } }
@media (prefers-reduced-motion:reduce) { *::after { scroll-behavior: auto!important; } }

/* ===== the cascade of every pair the conversion is lossy on — a clamp()/min()/max()
        value, or a multi-layer background — from 30-chapters.css. See push-site.mjs ===== */
.ch-arrival { min-height: 100svh; }
.re-stage { min-height: 100svh; }
.an-pin { min-height: 100svh; }
.an-card { width: min(19rem,72vw); }
.an-end { width: min(22rem,72vw); }
@media (hover:none) and (pointer:coarse), (max-width:767px) { .an-pin { min-height: 0; } }
.pr-pin { height: 100svh; }
.tr-pin { min-height: 100svh; }
.tr-media { max-height: 76svh; }
.tr-story blockquote { font-variation-settings: 'opsz' 28; }
@media (prefers-reduced-motion:reduce) { .tr-media { max-height: none; } }
@media (max-width:1023px) { .tr-media.tr-media { max-height: 44svh; } }
.ex-in { min-height: 100svh; }
@media (max-width:1023px) { .ex-in { min-height: 0; } }
.in-fields select { background-image: linear-gradient(45deg,transparent 50%,var(--gold) 50%),linear-gradient(135deg,var(--gold) 50%,transparent 50%); }
.in-fields select { background-position: calc(100% - 1.1rem) 50%,calc(100% - .75rem) 50%; }

