/* ==== 90-boot.js ==== */
/* ==========================================================================
   BOOT — register plugins (body exists now), create the smoother, flush the
   chapters, then the global UI: progress, chapter readout, nav state,
   anchors, magnetic buttons, cursor, drawer.
   ========================================================================== */
(function(){
  var W = window.WZ;
  document.documentElement.classList.add('wz-ready');
  var FINE = window.matchMedia('(hover:hover) and (pointer:fine)').matches;
  if (FINE) document.documentElement.classList.add('wz-fine');

  /* --- re-hydrate what Instatic's importer strips ---
     base.button flattens children to a label string and Link modules unwrap
     an only child, so the <span> inside every .btn (the label's z-index
     guarantee over the hover fill), the burger's two bars and the FAQ
     toggle's <i> glyph do not survive a round trip. Rebuilt here; a no-op
     wherever the markup arrived intact. Runs before the GSAP gate so the
     page is right even if the motion layer is absent. */
  document.querySelectorAll('.btn').forEach(function(b){
    if(b.querySelector('span') || !b.firstChild) return;
    var t = b.textContent.trim(); if(!t) return;
    var sp = document.createElement('span'); sp.textContent = t; b.textContent = ''; b.appendChild(sp);
  });
  document.querySelectorAll('.burger').forEach(function(b){
    if(b.querySelector('span')) return;
    b.appendChild(document.createElement('span')); b.appendChild(document.createElement('span'));
  });
  document.querySelectorAll('.faq-q').forEach(function(q){
    if(!q.querySelector('span')){ var t = q.textContent.trim(); q.textContent=''; var s=document.createElement('span'); s.textContent=t; q.appendChild(s); }
    if(!q.querySelector('i')) q.appendChild(document.createElement('i'));
    if(!q.hasAttribute('aria-expanded')) q.setAttribute('aria-expanded','false');
  });
  /* the hero film: one src attribute (importers keep attributes, not <source>
     children); phones get the 960 encode before the first play */
  document.querySelectorAll('video[data-src]').forEach(function(v){
    var mobile = v.getAttribute('data-src-mobile');
    v.src = (mobile && window.innerWidth < 768) ? mobile : v.getAttribute('data-src');
  });

  if(!W || !W.ok){
    document.querySelectorAll('[data-anim="hide"]').forEach(function(el){ el.style.visibility='visible'; });
    document.querySelectorAll('[data-wipe],.tr-shot,.pr-film').forEach(function(el){ el.style.clipPath='none'; });
    return;
  }

  gsap.registerPlugin(ScrollTrigger, ScrollToPlugin);
  if(window.ScrollSmoother) gsap.registerPlugin(ScrollSmoother);
  if(window.SplitText)      gsap.registerPlugin(SplitText);
  if(window.Observer)       gsap.registerPlugin(Observer);

  /* Smoother is desktop-only: with a smoother present ScrollTrigger pins by
     transform and phones drift against the finger. Touch is the condition. */
  var TOUCH = window.matchMedia('(hover:none) and (pointer:coarse)').matches;
  if(!W.reduced && !TOUCH && window.ScrollSmoother && document.getElementById('smooth-wrapper')){
    try{
      W.smoother = ScrollSmoother.create({ wrapper:'#smooth-wrapper', content:'#smooth-content',
        smooth: 1.15, effects: false, smoothTouch: false, normalizeScroll: false, ignoreMobileResize: true });
      document.documentElement.classList.add('wz-smooth');
    }catch(e){ console.warn('ScrollSmoother unavailable', e); }
  }

  W.flush();

  /* reading progress + chapter readout */
  var navCh = document.getElementById('navCh'), navNm = document.getElementById('navName'),
      navBar = document.getElementById('navBar'), navPr = document.getElementById('navProgress'),
      nav = document.getElementById('nav');
  gsap.to(navPr,{scaleX:1,ease:'none',scrollTrigger:{start:0,end:'max',scrub:.25}});
  var CHAPTERS = gsap.utils.toArray('section[data-chapter]');
  var LAST = CHAPTERS.reduce(function(m,s){ return Math.max(m, parseInt(s.getAttribute('data-chapter'),10)||0); }, 1);
  CHAPTERS.forEach(function(sec){
    var i = parseInt(sec.getAttribute('data-chapter'),10), name = sec.getAttribute('data-chapter-name');
    function activate(){
      if(navCh) navCh.textContent = String(i).padStart(2,'0');
      if(navNm) navNm.textContent = name;
      if(navBar) navBar.style.setProperty('--p', (i/LAST).toFixed(3));
      nav.classList.toggle('on-light', sec.getAttribute('data-theme') === 'light');
    }
    ScrollTrigger.create({trigger:sec,start:'top 55%',end:'bottom 45%',onEnter:activate,onEnterBack:activate});
    if (i === 0) activate();
  });
  ScrollTrigger.create({start:40,end:99999,onToggle:function(self){ nav.classList.toggle('is-solid', self.isActive); }});

  /* anchors through the smoother */
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click', function(e){
      var id = a.getAttribute('href'); if(id.length < 2) return;
      var t = document.querySelector(id); if(!t) return;
      e.preventDefault();
      if(W.smoother) W.smoother.scrollTo(t, true, 'top top');
      else gsap.to(window,{duration: W.reduced?0:1, scrollTo:{y:t,autoKill:true},ease:'power2.inOut'});
    });
  });

  /* magnetic buttons + cursor, fine pointers only */
  if(!W.reduced && FINE){
    document.querySelectorAll('.magnetic').forEach(function(el){
      var xTo = gsap.quickTo(el,'x',{duration:.5,ease:'power3'}), yTo = gsap.quickTo(el,'y',{duration:.5,ease:'power3'});
      el.addEventListener('pointermove',function(e){
        var r = el.getBoundingClientRect();
        xTo((e.clientX-r.left-r.width/2)*.22); yTo((e.clientY-r.top-r.height/2)*.38);
      });
      el.addEventListener('pointerleave',function(){ xTo(0); yTo(0); });
    });
    var cur = document.getElementById('cursor');
    if(cur){
      var cx = gsap.quickTo(cur,'x',{duration:.25,ease:'power3'}), cy = gsap.quickTo(cur,'y',{duration:.25,ease:'power3'});
      window.addEventListener('pointermove',function(e){ cx(e.clientX); cy(e.clientY); }, {passive:true});
      document.querySelectorAll('a,button,label,.an-card,.pf-quote').forEach(function(el){
        el.addEventListener('pointerenter',function(){ cur.classList.add('is-link'); });
        el.addEventListener('pointerleave',function(){ cur.classList.remove('is-link'); });
      });
    }
  }

  /* drawer */
  var burger = document.getElementById('burger'), drawer = document.getElementById('drawer');
  if (burger && drawer) {
    function closeDrawer(){
      burger.classList.remove('is-open'); drawer.classList.remove('is-open'); nav.classList.remove('is-menu-open');
      burger.setAttribute('aria-expanded','false'); drawer.setAttribute('aria-hidden','true');
      document.body.classList.remove('is-locked'); if(W.smoother) W.smoother.paused(false);
    }
    burger.addEventListener('click',function(){
      var open = drawer.classList.toggle('is-open');
      burger.classList.toggle('is-open',open); nav.classList.toggle('is-menu-open',open);
      burger.setAttribute('aria-expanded',String(open)); drawer.setAttribute('aria-hidden',String(!open));
      burger.setAttribute('aria-label', open?'Close menu':'Open menu');
      document.body.classList.toggle('is-locked',open); if(W.smoother) W.smoother.paused(open);
    });
    drawer.querySelectorAll('a').forEach(function(a){ a.addEventListener('click', closeDrawer); });
    document.addEventListener('keydown',function(e){ if(e.key==='Escape' && drawer.classList.contains('is-open')) closeDrawer(); });
  }

  if(document.fonts && document.fonts.ready) document.fonts.ready.then(function(){ ScrollTrigger.refresh(); });
  window.addEventListener('load', function(){ ScrollTrigger.refresh(); });
})();

/* Brandklout: Termly -> GoHighLevel consent bridge (v2.2.0)
   Copies each visitor's Termly choice into the hidden privacy_* fields of every embedded GHL form,
   survey or calendar, through the iframe URL (GHL prefills fields from matching query keys).
   Source of truth for Webflow (inline, footer) and Instatic (site script asset). Docs:
   deliver/process/23-termly-ghl-consent/23-termly-ghl-consent.md
   Per-site overrides, optional, set before this runs:
     window.BrandkloutConsentConfig = { marketingDisclosureVersion: "YYYY-MM-DD", privacyPolicyVersion: "" } */
(function () {
  if (window.BrandkloutConsentBridge) return;
  window.BrandkloutConsentBridge = "2.2.0";

  var custom = window.BrandkloutConsentConfig || {};
  var CONFIG = {
    // Written to marketing_disclosure_version. Bump it when the SMS/email consent wording on the form changes.
    marketingDisclosureVersion: custom.marketingDisclosureVersion || "2026-09-16",
    // Written to privacy_policy_version. Empty uses the document version ID Termly reports.
    privacyPolicyVersion: custom.privacyPolicyVersion || ""
  };

  var FORM_PATH = /\/widget\/(form|survey|booking)\//;

  // Termly's saved record for this visitor, or null before they choose.
  function termlyRecord() {
    try {
      var cache = JSON.parse(localStorage.getItem("TERMLY_API_CACHE") || "{}");
      var entry = cache.TERMLY_COOKIE_CONSENT;
      return entry && entry.value ? { value: entry.value, createdAt: entry.createdAt } : null;
    } catch (e) { return null; }
  }

  function termlyState() {
    try { return window.Termly.getConsentState(); } catch (e) { return null; }
  }

  // Until the visitor answers the banner (or while Termly is not installed), the form records the
  // same values a Decline click would.
  function values() {
    var record = termlyRecord();
    var saved = record ? record.value : {};
    var state = record ? (termlyState() || saved) : {};
    var gpc = navigator.globalPrivacyControl === true || saved.gpc === true;
    var optOut = gpc || state.do_not_sell === true || state.advertising !== true;
    var ads = state.advertising === true && !optOut ? "granted" : "denied";

    // Every key is a GHL custom field key; GHL prefills a field from the query parameter of the same name.
    var p = "privacy_";
    var v = { marketing_disclosure_version: CONFIG.marketingDisclosureVersion };
    v[p + "analytics_consent"] = state.analytics === true ? "granted" : "denied";
    v[p + "advertising_consent"] = v[p + "ad_user_data_consent"] = v[p + "ad_personalization_consent"] = ads;
    v[p + "sale_share_opt_out"] = String(optOut);
    v[p + "gpc_detected"] = String(gpc);
    v[p + "consent_timestamp_utc"] = record && record.createdAt ? new Date(record.createdAt).toISOString() : "";
    v[p + "policy_version"] = CONFIG.privacyPolicyVersion || String(saved.document_version_id || "");
    v[p + "cmp_receipt_id"] = saved.visitor_id || (saved.visitor && saved.visitor.uuid) || "";
    v[p + "source_url"] = location.origin + location.pathname;
    return v;
  }

  function withConsent(src) {
    var url = new URL(src, location.href);
    var v = values();
    for (var name in v) {
      if (v[name]) url.searchParams.set(name, v[name]); else url.searchParams.delete(name);
    }
    return url.toString();
  }

  function update() {
    var frames = document.querySelectorAll("iframe");
    for (var i = 0; i < frames.length; i++) {
      var src = frames[i].getAttribute("src") || "";
      if (!FORM_PATH.test(src)) continue;
      var next = withConsent(src);
      if (src !== next) frames[i].setAttribute("src", next);
    }
  }

  var queued = false;
  function schedule() {
    if (queued) return;
    queued = true;
    setTimeout(function () { queued = false; update(); }, 50);
  }

  update();
  new MutationObserver(schedule).observe(document.documentElement, {
    childList: true, subtree: true, attributes: true, attributeFilter: ["src"]
  });

  // Termly loads async; re-run when it is ready and each time the visitor changes their choice.
  (function hook(tries) {
    var termly = window.Termly;
    if (termly && termly.on) {
      termly.on("initialized", schedule);
      termly.on("consent", schedule);
      schedule();
    } else if (tries < 100) {
      setTimeout(function () { hook(tries + 1); }, 100);
    }
  })(0);
})();

/* Brandklout: Termly "Cookie Preferences" footer control (v1.2.0)
 *
 * WHY A SCRIPT AND NOT HTML IN THE FOOTER. The kit's static
 * kit/consent-preferences-link.html is still the right answer wherever a human
 * is editing one footer. It does not scale to this rollout:
 *   - Instatic inlines the footer into EVERY page (57 of them on dr-nahlah), and
 *     a page write through PUT /site-document drops seoTitle/seoDescription and
 *     needs a PATCH to restore them -- which flattens every `a/b` slug's route.
 *   - Webflow's footer is a Designer layout. The Data API can write site-wide
 *     freeform head/footer CODE, but cannot place a link inside the footer nav;
 *     only the Designer can, and that needs a human with the browser open.
 * So the control is inserted at runtime, from a file that is already site-wide
 * on both platforms. The link does nothing without JavaScript anyway.
 *
 * HOW IT PLACES ITSELF. It finds the footer's Privacy Policy and Terms links,
 * works out the REPEATING UNIT those two share -- the `<a>` itself, or the
 * `<li>`/`<span>` each is wrapped in -- and clones it. Cloning is what makes one
 * file work on 29 unrelated designs: the control inherits that site's exact
 * typography, colour, spacing and hover without a line of CSS from us. Any
 * separator between the two units (a "|", a bullet, a styled span) is cloned
 * with it, so the new item is punctuated like its neighbours.
 *
 * SIZE. Webflow caps a registered inline script at 2,000 characters and the
 * minified build must stay under it -- `node consent-kit.mjs minify` fails the
 * run otherwise. That is why this file has no defensive extras.
 */
(function () {
  if (window.BrandkloutConsentPreferences) return
  window.BrandkloutConsentPreferences = '1.2.0'

  var LABEL = (window.BrandkloutConsentConfig || {}).preferencesLabel || 'Cookie Preferences'
  // Plain substrings, not regexes, and deliberately so: this file is transcribed
  // into Webflow's register_inline_script through a tool call, and an escape
  // sequence such as \s can lose a backslash layer on the way. No backslash in
  // the source means nothing to lose. `minify` fails the run if one appears.
  var PRIVACY = ['privacy', 'private-policy', 'private policy']
  var SECOND = ['terms', 'cookie', 'accessib', 'disclaim', 'hipaa', 'conditions']

  function matches(el, words) {
    var t = (el.textContent + ' ' + el.getAttribute('href')).toLowerCase()
    for (var i = 0; i < words.length; i++) if (t.indexOf(words[i]) > -1) return true
    return false
  }

  function openModal(e) {
    e.preventDefault()
    // Termly's own API. The .termly-display-preferences class alone is enough
    // once Termly has loaded, but binding here means the control also works if
    // Termly attached its delegated listener before this node existed.
    if (typeof window.displayPreferenceModal === 'function') window.displayPreferenceModal()
  }

  /** Raise a and b until they are siblings; null if they never meet. */
  function align(a, b) {
    while (a.parentElement && !a.parentElement.contains(b)) a = a.parentElement
    if (!a.parentElement) return null
    while (b.parentElement && b.parentElement !== a.parentElement) b = b.parentElement
    return b.parentElement && a !== b ? [a, b] : null
  }

  function build(unit) {
    var copy = unit.cloneNode(true)
    var link = copy.matches('a[href]') ? copy : copy.querySelector('a[href]')
    if (!link) return null
    copy.removeAttribute('id')
    // Relabel the deepest element that actually held the text, so a link built
    // as <a><span>Privacy Policy</span></a> keeps its span.
    var holder = link
    while (holder.children.length === 1 && !(holder.childNodes[0] || {}).nodeValue) holder = holder.children[0]
    holder.textContent = LABEL
    link.setAttribute('href', '#')
    link.className += ' termly-display-preferences'
    link.addEventListener('click', openModal)
    return copy
  }

  function insert() {
    if (document.querySelector('.termly-display-preferences')) return
    var all = document.querySelectorAll('footer a[href], [class*="foot"] a[href], [id*="foot"] a[href]')
    var privacy = null
    var other = null
    for (var i = 0; i < all.length; i++) {
      if (!privacy && matches(all[i], PRIVACY)) privacy = all[i]
      else if (privacy && !other && matches(all[i], SECOND)) other = all[i]
    }
    if (!privacy) return
    var pair = other && align(privacy, other)
    if (!pair) {
      var solo = build(privacy)
      if (solo) privacy.parentNode.insertBefore(solo, privacy.nextSibling)
      return
    }
    // Append after the LAST of the two, reading "Privacy Policy | Terms | Cookie
    // Preferences" rather than wedging the new item into the middle.
    var first = pair[0].compareDocumentPosition(pair[1]) & 4 ? pair[0] : pair[1]
    var last = first === pair[0] ? pair[1] : pair[0]
    var unit = build(last)
    if (!unit) return
    var at = last.nextSibling
    // Clone the separator, if this design has one between its legal items.
    for (var n = first.nextSibling; n && n !== last; n = n.nextSibling) {
      if (n.nodeType !== 3 || n.nodeValue.trim().length <= 3) last.parentNode.insertBefore(n.cloneNode(true), at)
    }
    last.parentNode.insertBefore(unit, at)
  }

  // Two shots: the footer is server-rendered HTML on both platforms, so
  // DOMContentLoaded is enough, and `load` covers a footer built by a script.
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', insert)
  else insert()
  window.addEventListener('load', insert)
})()
